$lines=[['accountId'=>'ar','debit'=>'0.30','credit'=>'0'],['accountId'=>'sales','debit'=>'0','credit'=>'0.30']];
rejects(fn()=>postJournal($pdo,'b','2026-09-11','Test',$lines,'u'));
